def handle(app, svc):
    resp = svc.apply(app)
    # API v2 response: {"api_version": 2, "result": {"outcome": ..., "credit_limit": ...}}
    result = resp.get("result", resp) if isinstance(resp, dict) else {}
    outcome = result.get("outcome")
    limit = result.get("credit_limit", 0)
    try:
        limit = int(limit)
    except (TypeError, ValueError):
        limit = 0
    if outcome == "approved":
        return {"action": "issue", "limit": limit}
    if outcome == "manual_review":
        return {"action": "queue_review", "limit": 0}
    return {"action": "decline", "limit": 0}

